  background: #000;
  position: relative;
  overflow: hidden;
}
.z-player * {
  font-family: Consolas, "Noto Mono", "Noto Sans Mono", "微软雅黑", Arial, sans-serif;
  box-sizing: content-box;
  font-size: 13px;
  -webkit-font-smoothing: antialiased;
}
.z-player.z-player-fulled {
  position: fixed !important;
  z-index: 100000 !important;
  left: 0 !important;
  top: 0 !important;
  width: 100% !important;
  height: 100% !important;
  transform: translate(0, 0) !important;
}
.z-player svg {
  width: 100%;
  height: 100%;
}
.z-player svg path,
.z-player svg circle {
  fill: #fff;
}
.z-player .z-player_video {
  width: 100%;
  height: 100%;
  display: none;
}
.z-player .z-player_wrap {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
}
.z-player .z-player_top {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  transition: all 0.2s ease;
}
.z-player .z-player_bottom {
  width: calc(100% - 32px);
  height: 55px;
  padding: 0 16px;
  transition: all 0.2s ease;
  position: absolute;
  bottom: 0;
  left: 0;
  background-image: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.4));
  z-index: 10;
}
.z-player .z-player_bottom * {
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
}
.z-player .z-player_notice {
  background-color: rgba(0, 0, 0, 0.6);
  color: #fff;
  position: absolute;
  padding: 2px 10px 4px 10px;
  text-align: center;
  border-radius: 4px;
  left: 50%;
  transition: all 0.2s ease;
  transform: translate(-50%, -50%);
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
}
.z-player_controller-bar {
  position: relative;
  background: rgba(128, 128, 128, 0.4);
  width: 100%;
  margin-top: 5px;
  margin-bottom: 8px;
  height: 5px;
  cursor: pointer;
}
.z-player_controller-bar:hover .z-player_controller-bar_played .z-player_controller-bar_thumb {
  transform: scale(1);
}
.z-player_controller-bar .z-player_controller-bar_highlight {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.z-player_controller-bar .z-player_controller-bar_highlight .z-player_controller-bar_highlight-item {
  position: absolute;
  background: rgba(255, 255, 255, 0.8);
  color: rgba(255, 255, 255, 0.8);
  top: 0;
  width: 5px;
  height: 5px;
}
.z-player_controller-bar .z-player_controller-bar_time {
  position: absolute;
  top: -28px;
  border-radius: 4px;
  padding: 4px 8px;
  background-color: rgba(0, 0, 0, 0.8);
  color: #fff;
  text-align: center;
  word-wrap: normal;
  word-break: normal;
}
.z-player_controller-bar .z-player_controller-bar_loaded {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0.5;
  height: 100%;
  background: #fff;
  transition: all 0.2s ease;
  will-change: width;
}
.z-player_controller-bar .z-player_controller-bar_played {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0.8;
  height: 100%;
  background: deepskyblue;
}
.z-player_controller-bar .z-player_controller-bar_played .z-player_controller-bar_thumb {
  position: absolute;
  background: deepskyblue;
  top: 0;
  right: 5px;
  margin-top: -4px;
  margin-right: -10px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  transition: all 0.2s ease-in-out;
  transform: scale(0);
}
.z-player_controller-box {
  flex: 1;
  width: 100%;
  margin-bottom: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.z-player_controller-box .z-player_controller-box-icon {
  width: 40px;
  height: 35px;
  padding: 0 8px;
  outline: none;
  cursor: pointer;
  vertical-align: middle;
  box-sizing: border-box;
  display: inline-block;
  transition: all 0.2s ease-in-out;
  opacity: 0.5;
}
.z-player_controller-box .z-player_controller-box-icon:hover {
  opacity: 1;
}
.z-player_controller-box .z-player_controller-box_left {
  flex: 1;
  display: flex;
  align-items: center;
}
.z-player_controller-box .z-player_controller-box_left .z-player_controller-box-time {
  color: #fff;
  margin-left: 4px;
  white-space: nowrap;
}
.z-player_controller-box .z-player_controller-box_right {
  position: relative;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.z-player_controller-volume-wrap {
  position: absolute;
  left: 40px;
  top: -100px;
  width: 32px;
  margin: 0 4px;
  padding: 5px 0;
  height: 70px;
  background-color: rgba(0, 0, 0, 0.8);
  color: #fff;
  text-align: center;
  border-radius: 4px;
  transition: all 0.2s ease;
}
.z-player_controller-volume-wrap .z-player_controller-volume-bar {
  position: absolute;
  width: 4px;
  background: gray;
  left: 14px;
  bottom: 10px;
  height: 42px;
  cursor: pointer;
}
.z-player_controller-volume-wrap .z-player_controller-volume-bar .z-player_controller-volume-bar_current {
  position: absolute;
  width: 100%;
  background: deepskyblue;
  left: 0;
  bottom: 0;
  will-change: width;
}
.z-player_controller-volume-wrap .z-player_controller-volume-bar .z-player_controller-volume-bar_current .z-player_controller-volume-bar_thumb {
  position: absolute;
  background: deepskyblue;
  top: 0;
  right: 6px;
  margin-top: -6px;
  margin-right: -10px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
}
.z-player_controller-rate-wrap {
  position: absolute;
  left: 0;
  top: -130px;
  width: 40px;
  margin: 0 4px;
  padding: 5px 0;
  height: 100px;
  background-color: rgba(0, 0, 0, 0.8);
  color: #fff;
  text-align: center;
  border-radius: 4px;
  transition: all 0.2s ease;
}
.z-player_controller-rate-wrap .z-player_controller-rate-value {
  height: 20px;
  line-height: 20px;
  width: 100%;
  text-align: center;
  cursor: pointer;
}
.z-player_controller-rate-wrap .z-player_controller-rate-value:hover,
.z-player_controller-rate-wrap .z-player_controller-rate-value.z-player_controller-rate-checked {
  background-color: deepskyblue;
  opacity: 0.8;
}
.z-player-danmu {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
}
.z-player-danmu * {
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
}
.z-player-danmu .z-player-danmu-item {
  position: absolute;
  box-sizing: border-box;
  padding: 0 4px;
  border-radius: 0.1em;
  text-shadow: 1px 0 1px #000, 0 1px 1px #000, 0 -1px 1px #000, -1px 0 1px #000;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: nowrap;
}
.z-player-danmu .z-player-danmu-item:hover {
  animation-play-state: paused !important;
  z-index: 1;
}
.z-player-danmu .z-player-danmu-item_right {
  right: 0;
  transform: translateX(100%);
  -webkit-animation-name: 'danmu-right';
}
.z-player-danmu .z-player-danmu-item_right.z-player-danmu-item_move {
  will-change: transform;
  animation-name: 'danmu-right';
  animation-timing-function: linear;
}
.z-player-danmu .z-player-danmu-item_top,
.z-player-danmu .z-player-danmu-item_bottom {
  left: 50%;
  transform: translate(-50%, 0);
  -webkit-animation-name: 'danmu-center';
}
.z-player-danmu .z-player-danmu-item_top.z-player-danmu-item_move,
.z-player-danmu .z-player-danmu-item_bottom.z-player-danmu-item_move {
  will-change: visibility;
  animation-name: 'danmu-center';
  animation-timing-function: linear;
}
@keyframes danmu-right {
  from {
    transform: translateX(100%);
  }
}
@keyframes danmu-center {
  from {
    visibility: visible;
  }
  to {
    visibility: visible;
  }
}
.z-player-danmu_mask {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 2;
}
.z-player-switch {
  width: 32px;
  height: 20px;
  text-align: center;
  font-size: 0;
  vertical-align: middle;
  opacity: 0.8;
}
.z-player-switch input {
  max-height: 0;
  max-width: 0;
  display: none;
}
.z-player-switch input + label {
  display: inline-block;
  position: relative;
  box-shadow: #fff 0 0 0 0 inset;
  border: 1px solid #fff;
  height: 20px;
  width: 32px;
  border-radius: 10px;
  box-sizing: border-box;
  cursor: pointer;
  transition: 0.2s ease-in-out;
}
.z-player-switch input + label:before {
  content: "";
  position: absolute;
  display: block;
  height: 18px;
  width: 18px;
  top: 0;
  left: 0;
  border-radius: 15px;
  transition: 0.2s ease-in-out;
}
.z-player-switch input + label:after {
  content: "";
  position: absolute;
  display: block;
  left: 0;
  top: 0;
  border-radius: 15px;
  background: #fff;
  transition: 0.2s ease-in-out;
  height: 18px;
  width: 18px;
}
.z-player-switch input:checked + label {
  background: deepskyblue;
}
.z-player-switch input:checked + label:before {
  width: 30px;
  background: deepskyblue;
}
.z-player-switch input:checked + label:after {
  left: 12px;
}
